selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for combo in combinations(options, k):
        ids = []
        for row in combo:
            ids = ids + [row['id']]
        if valid(ids):
            result = ids
            break
    if result:
        break

selected.effects:
artifact = read('/output/selection')
if artifact is None:
    write('/output/selection', result)
    selection = result
else:
    selection = artifact
receipt_state = receipt('report')
if receipt_state == 'success':
    delivery_state = 'sent'
elif receipt_state == 'unknown':
    delivery_state = status('report')
else:
    delivery_state = status('report')
if delivery_state == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
